-- ----------------------------
-- Table structure for players
-- ----------------------------
DROP TABLE IF EXISTS `players`;
CREATE TABLE `players` (
  `id` varchar(255) DEFAULT NULL,
  `account` varchar(255) DEFAULT NULL,
  `passwd` varchar(255) DEFAULT NULL,
  `serverindex` varchar(255) DEFAULT NULL,
  `updatetime` varchar(255) DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of players
-- ----------------------------

-- ----------------------------
-- Table structure for server
-- ----------------------------
DROP TABLE IF EXISTS `server`;
CREATE TABLE `server` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8 DEFAULT NULL COMMENT '服务器名字',
  `ip` varchar(255) CHARACTER SET utf8 DEFAULT NULL COMMENT '服务器ip',
  `port` varchar(255) DEFAULT NULL COMMENT '服务器端口',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1000 DEFAULT CHARSET=latin1 ROW_FORMAT=COMPACT;

-- ----------------------------
-- Records of server
-- ----------------------------
INSERT INTO `server` VALUES ('1', '1区', '123.207.28.168', '9001');
INSERT INTO `server` VALUES ('2', '2区', '123.207.28.168', '9002');
INSERT INTO `server` VALUES ('999', '999区', '123.207.28.168', '9999');

-- ----------------------------
-- Table structure for serverroute
-- ----------------------------
DROP TABLE IF EXISTS `serverroute`;
CREATE TABLE `serverroute` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `serverid` int(11) DEFAULT NULL COMMENT '服务器id',
  `hostname` varchar(124) DEFAULT NULL COMMENT '网关的ip或者名字',
  `port` int(11) DEFAULT NULL COMMENT '网关的端口',
  `name` varchar(255) DEFAULT '' COMMENT '服务器名',
  `opentime` datetime DEFAULT NULL COMMENT '开服时间',
  `realid` int(11) DEFAULT NULL COMMENT '真实ID',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=1000 DEFAULT CHARSET=utf8 COMMENT='路由数据表';

-- ----------------------------
-- Records of serverroute
-- ----------------------------
INSERT INTO `serverroute` VALUES ('1', '1', '106.54.121.86', '9001', '1区', '2020-06-08 13:00:00', '1');

-- ----------------------------
-- Procedure structure for loadserverroute
-- ----------------------------
DROP PROCEDURE IF EXISTS `loadserverroute`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `loadserverroute`()
begin
select serverid,hostname,port from serverroute ;
end
;;
DELIMITER ;
